with T["Compare"]:
    mode=st.selectbox("Comparison",["Year over Year","Month over Month"])
    if mode=="Year over Year":
        df=Q(f'SELECT mon "month",yr "year",{agg} v FROM joined WHERE {WHERE} GROUP BY 1,2 ORDER BY 1,2')
        df["year"]=df["year"].astype(int); years=sorted(df["year"].unique())
        greys=["#d4d7e0","#b3b8c6","#9aa1b0","#6b7280","#2c3142"]
        cmap={str(y):greys[min(i,len(greys)-1)] for i,y in enumerate(years)}
        if years: cmap[str(years[-1])]="#6366f1"            # latest year = accent, older greyscaled
        df["year"]=df["year"].astype(str)
        fig=px.line(df,x="month",y="v",color="year",title=f"YoY {mlab}",color_discrete_map=cmap); fig.update_traces(mode="lines")
        for y in years:
            sub=df[df["year"]==str(y)].sort_values("month")
            if len(sub): fig.add_annotation(x=sub["month"].iloc[-1],y=sub["v"].iloc[-1],text=str(y),showarrow=False,xanchor="left",xshift=8,font=dict(family="Inter",size=11.5,color=cmap[str(y)]))
        fig.update_layout(height=420,showlegend=False,margin=dict(r=54),xaxis_title="Month")
        plot(fig,width="stretch")
    else:
        df=Q(f"SELECT date_trunc('month',date) period,{agg} v FROM joined WHERE {WHERE} GROUP BY 1 ORDER BY 1"); df["MoM %"]=(df["v"].pct_change()*100).round(1)
        fig=go.Figure(); fig.add_bar(x=df["period"],y=df["v"],name=mlab,marker_color="#6366f1")
        fig.add_trace(go.Scatter(x=df["period"],y=df["MoM %"],name="MoM %",yaxis="y2",mode="lines+markers",line=dict(color="#f43f5e")))
        fig.update_layout(height=440,yaxis=dict(title=mlab),yaxis2=dict(title="MoM %",overlaying="y",side="right"))
        plot(fig,width='stretch')

with T["SKUs"]:
    n=st.slider("Top N SKUs",5,50,15)
    _attr=CAT+LABEL                                          # describe each SKU with product name + colour + size
    def _pickcol(*subs):
        for c in _attr:                                      # exact match first...
            if c.lower().strip() in subs: return c
        for c in _attr:                                      # ...then contains
            if any(s in c.lower() for s in subs): return c
        return None
    desc=[c for c in [_pickcol("product_name","product name","name"),_pickcol("color","colour"),_pickcol("size")] if c]
    sel=", ".join(["sku"]+[f'"{c}"' for c in desc])
    ord_expr=("COUNT(DISTINCT reference_code)" if _HAS_REF else "COUNT(*)")
    _orderby={"subtotal":"rev","qty":"units","orders":"orders"}[metric]
    df=Q(f'SELECT {sel}, SUM(subtotal) rev, SUM(qty) units, {ord_expr} orders FROM joined WHERE {WHERE} GROUP BY {sel} ORDER BY {_orderby} DESC LIMIT {n}')
    _mv=float(df["rev"].max()) if len(df) else 1.0       # empty filter → NaN guard for the progress bar
    if _mv!=_mv or _mv<=0: _mv=1.0
    cfg={"rev":st.column_config.ProgressColumn("Revenue (₹)",format="₹%d",min_value=0,max_value=_mv),
         "units":st.column_config.NumberColumn("Units",format="%d"),
         "orders":st.column_config.NumberColumn("Orders",format="%d")}
    st.dataframe(df,width="stretch",hide_index=True,column_config=cfg)

with T["Pivot"]:
    # Columns dropdown: time options + only LOW-cardinality dims (so we never try to
    # render thousands of columns, which breaks the table). High-cardinality fields
    # like product_name / Color are fine for ROWS but not for COLUMNS.
    def _card(col):
        try: return con.execute(f'SELECT COUNT(DISTINCT "{col}") FROM joined').fetchone()[0]
        except Exception: return 9999
    dim_opts=(CAT if CAT else [])+["marketplaces"]
    low_card_dims=[c for c in dim_opts if _card(c)<=30]
    col_opts=["Month (YYYY-MM)","Week (start)","Day (YYYY-MM-DD)","Quarter","Year"]+low_card_dims
    cpa,cpb=st.columns(2)
    rd=cpa.selectbox("Rows",dim_opts,key="piv_rows")
    cd=cpb.selectbox("Columns",col_opts,key="piv_cols")
    if cd=="Month (YYYY-MM)":
        col_sql="yr||'-'||lpad(mon::VARCHAR,2,'0')"; order_sql="2"
    elif cd=="Week (start)":
        col_sql="strftime(date_trunc('week',date),'%Y-%m-%d')"; order_sql="2"
    elif cd=="Day (YYYY-MM-DD)":
        col_sql="strftime(date,'%Y-%m-%d')"; order_sql="2"
    elif cd=="Year":
        col_sql="CAST(yr AS VARCHAR)"; order_sql="2"
    elif cd=="Quarter":
        col_sql="yr||'-Q'||CAST(CEIL(mon/3.0) AS INT)"; order_sql="2"
    else:
        col_sql=f'"{cd}"'; order_sql="1"
    extra_where=f' AND {col_sql} IS NOT NULL' if cd in low_card_dims else ''
    df=Q(f'SELECT "{rd}" r, {col_sql} c, {agg} v FROM joined WHERE {WHERE} AND "{rd}" IS NOT NULL{extra_where} GROUP BY 1,2 ORDER BY {order_sql}')
    if df.empty:
        st.info("No data for this selection.")
    elif df["c"].nunique()>80:
        # guard: Day/Week over a long range would build a huge table (and OOM the host) -> ask for a coarser column
        st.warning(f"'{cd}' would make {df['c'].nunique():,} columns over this date range — too wide to render. "
                   "Pick a coarser column (Month / Quarter / Year) or narrow the date range.")
    else:
        piv=df.pivot(index="r",columns="c",values="v").fillna(0)
        piv["Total"]=piv.sum(axis=1)
        piv=piv.sort_values("Total",ascending=False)
        vmax=float(piv.drop(columns="Total").values.max() or 1)
        def _heat(col):                                      # value-shaded cells (no matplotlib) — darker = higher
            out=[]
            for v in col:
                if col.name=="Total":
                    out.append("font-weight:700;color:#0f1115;background:#f3f4fb")
                else:
                    a=0 if vmax<=0 else max(0.0,min(0.55,float(v)/vmax))
                    out.append(f"background-color:rgba(99,102,241,{a:.3f});color:{'#fff' if a>=0.42 else '#0f1115'}")
            return out
        st.caption(f"{len(piv):,} rows · {len(piv.columns)-1} columns · darker = higher")
        st.dataframe(piv.style.format(ind_group).apply(_heat,axis=0),width='stretch',height=480)
        st.download_button("Download CSV",piv.to_csv().encode(),"pivot.csv","text/csv")

with T["Ask AI"]:
    st.subheader("Ask AI")
    if not GEMINI_API_KEY:
        st.info(
            "**Assistant is off.** Add a Gemini API key to switch it on. In `.streamlit/secrets.toml`:\n\n"
            "```toml\nGEMINI_API_KEY = \"your-key-here\"\n"
            "# optional, defaults to gemini-2.0-flash-lite\nGEMINI_MODEL = \"gemini-2.0-flash-lite\"\n```\n\n"
            "The key is read from `st.secrets` (gitignored) — never paste it into the code. Rerun after saving.")
    else:
        st.caption("Ask in plain English — questions are translated to SQL and run on your live data. "
                   "Aggregates use the dashboard's definitions (Subtotal · Units · Orders). "
                   "Note: the sidebar filters are not applied here — mention the period/segment in your question.")
        if "ai_msgs" not in st.session_state: st.session_state["ai_msgs"]=[]

        for turn in st.session_state["ai_msgs"]:
            with st.chat_message("user"): st.markdown(turn["q"])
            with st.chat_message("assistant"):
                if turn.get("error"): st.error(turn["error"])
                else:
                    if turn.get("answer"): st.markdown(turn["answer"])
                    _render_result(turn.get("df"))
                if turn.get("sql"):
                    with st.expander("Show SQL"): st.code(turn["sql"],language="sql")

        pending=None
        examples=["Top 10 SKUs by revenue","Monthly revenue trend in 2025",
                  "Revenue share by channel","Total units sold"]
        ecols=st.columns(len(examples))
        for i,e in enumerate(examples):
            if ecols[i].button(e,key=f"ai_ex_{i}"): pending=e
        explain=st.checkbox("Also write a one-line answer (uses a 2nd request)",value=True,
                            help="Turn off to spend only one Gemini request per question — useful on the free tier.")
        with st.form("ai_form",clear_on_submit=True):
            qin=st.text_input("Your question",placeholder="e.g. Which colour sold the most units last month?")
            if st.form_submit_button("Ask") and qin.strip(): pending=qin.strip()

        if pending:
            turn={"q":pending}
            with st.spinner("Thinking…"):
                try:
                    sl="\n".join(f"  {n} : {t}" for n,t in ai_schema())
                    sql=_gen_sql(pending, sl)                       # cached + retries transient throttling
                    turn["sql"]=sql
                    if not _safe_select(sql):
                        turn["error"]="That request didn't produce a safe read-only SELECT. Try rephrasing."
                    else:
                        turn["df"]=Q(f"SELECT * FROM ({sql}) AS _ai LIMIT {AI_ROW_CAP}")
                        if explain:                                 # optional 2nd call — skip to save quota
                            try:
                                turn["answer"]=_gemini(
                                    f"Question: {pending}\n\nResult (CSV):\n{turn['df'].head(50).to_csv(index=False)}",
                                    system=_ANS_SYS)
                            except Exception:
                                turn["answer"]=None
                except Exception as e:
                    turn["error"]=f"AI request failed: {e}"
            st.session_state["ai_msgs"].append(turn)
            st.rerun()
